ironhail(c, t, cf, P){
  for (let i = 0; i < 8; i++){
    const a = i * TAU / 8 + t * 0.3, d = 0.3 + cf * 0.56;
    c.save(); c.translate(Math.cos(a) * d, Math.sin(a) * d); c.rotate(a + Math.PI / 2);
    SG.poly(c, [[0, -0.24], [0.15, 0.1], [0, 0.02], [-0.15, 0.1]], P.core, 0.5 + cf * 0.5);
    c.restore();
  }
  SG.ring(c, 0, 0, 0.2, P.glow, 0.07, 0.6);
},

